package com.vault.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="users",indexes=@Index(name="idx_user_email",columnList="email",unique=true)) public class User{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(nullable=false,length=120) private String name;@Column(nullable=false,unique=true,length=190) private String email;@Column(name="password_hash",nullable=false) private String passwordHash;@Column(name="created_at",nullable=false) private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now();protected User(){}public User(String n,String e,String p){name=n;email=e.toLowerCase();passwordHash=p;}@PreUpdate void touch(){updatedAt=Instant.now();}public UUID getId(){return id;}public String getName(){return name;}public void setName(String n){name=n;}public String getEmail(){return email;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String x){passwordHash=x;}public Instant getCreatedAt(){return createdAt;}}
